export function getBm3Timings(marks, timingConfigs) {
  const bm3Timings = {};
  if (!marks || !timingConfigs) {
    return bm3Timings;
  }
  timingConfigs.forEach(item => {
    if (!item.startMark || !item.endMark) {
      return;
    }
    const startTime = marks[item.startMark];
    if (!startTime) {
      return;
    }
    const endTime = marks[item.endMark];
    if (!endTime) {
      return;
    }
    bm3Timings[item.key] = {
      startTime,
      endTime
    };
  });
  return bm3Timings;
}